-- Production-safe starter tour packages. Run after seed.sql (needs its destinations).
-- Every tour is QUOTE_ONLY: no prices are published, the owner quotes each request.
-- Routes are classic, widely-run Sri Lanka itineraries; adjust or unpublish them in
-- Admin → Tours. Idempotent: existing slugs are left untouched.

insert into public.tours (slug, name, short_description, description, categories, duration_days, duration_nights,
  traveler_types, vehicle_options, max_group_size, price_mode, inclusions, exclusions, add_ons,
  cover_image_url, cover_image_alt, image_credit, seo_title, seo_description, is_featured, status, sort_order)
values
('cultural-triangle-and-hill-country', 'Cultural Triangle & Hill Country',
 'Rock fortresses, cave temples, Kandy and the tea hills at an unhurried pace.',
 'A classic first journey through Sri Lanka''s ancient cities and cool tea country, with a private driver throughout. Climb Sigiriya at sunrise, explore the Dambulla cave temples, spend an evening in Kandy and ride the hill-country train to Ella. Every day can be adjusted to your interests and pace.',
 array['cultural', 'hill-country', 'scenic-train', 'round-tour'], 7, 6,
 array['Couples', 'Families', 'First-time visitors'], array['Car', 'SUV', 'Van'], 12, 'QUOTE_ONLY',
 array['Private air-conditioned vehicle with English-speaking driver', 'Fuel, parking and highway tolls', 'Airport pickup and drop-off', 'Driver''s meals and accommodation'],
 array['International flights', 'Accommodation unless arranged in your quotation', 'Entrance tickets', 'Meals', 'Personal expenses and tips'],
 '[{"name":"Reserved train seats","description":"Kandy or Nanu Oya to Ella, subject to availability"},{"name":"Jeep safari at Minneriya or Kaudulla","description":"Elephant gathering, roughly July to October"}]'::jsonb,
 'https://images.unsplash.com/photo-1612862862126-865765df2ded', 'Aerial view of the Sigiriya rock fortress rising above dense green forest', 'Photo: Dylan Shaw / Unsplash',
 'Cultural Triangle & Hill Country 7-day private tour', 'A 7-day private Sri Lanka tour through Sigiriya, Dambulla, Kandy, Nuwara Eliya and Ella with your own driver.',
 true, 'published', 1),

('classic-sri-lanka-10-days', 'Classic Sri Lanka in 10 Days',
 'The island''s highlights in one loop: ancient cities, tea country, a leopard safari and the south coast.',
 'The most popular way to see Sri Lanka on a first visit. Start in the Cultural Triangle, head up into the hills by road and rail, drop down to Yala for a safari, then finish with Galle Fort and the beaches of the south coast before returning to the airport.',
 array['round-tour', 'cultural', 'hill-country', 'wildlife', 'beach', 'scenic-train'], 10, 9,
 array['Couples', 'Families', 'First-time visitors', 'Friends'], array['Car', 'SUV', 'Van'], 12, 'QUOTE_ONLY',
 array['Private air-conditioned vehicle with English-speaking driver', 'Fuel, parking and highway tolls', 'Airport pickup and drop-off', 'Driver''s meals and accommodation'],
 array['International flights', 'Accommodation unless arranged in your quotation', 'Entrance tickets and safari jeep', 'Meals', 'Personal expenses and tips'],
 '[{"name":"Reserved train seats","description":"Hill-country train, subject to availability"},{"name":"Yala safari jeep","description":"Half-day or full-day, with park fees"},{"name":"Whale watching from Mirissa","description":"Roughly November to April"}]'::jsonb,
 'https://images.unsplash.com/photo-1578519050142-afb511e518de', 'A train crossing a bridge through the forest near Ella', 'Photo: Anton Lecock / Unsplash',
 'Classic Sri Lanka 10-day private round tour', 'Ten days with your own driver: Sigiriya, Kandy, Ella, Yala, Galle and the south coast beaches. Tailored to you.',
 true, 'published', 2),

('grand-tour-of-sri-lanka-14-days', 'Grand Tour of Sri Lanka',
 'Two unhurried weeks: ancient capitals, tea country, safari, whales and beach time.',
 'For travellers who want to see the island properly without rushing. This route adds the ancient capital of Polonnaruwa, a night in the tea estates, an extra safari day and several slow days on the south and west coasts.',
 array['round-tour', 'cultural', 'hill-country', 'wildlife', 'beach', 'scenic-train'], 14, 13,
 array['Couples', 'Families', 'Slow travellers'], array['Car', 'SUV', 'Van'], 12, 'QUOTE_ONLY',
 array['Private air-conditioned vehicle with English-speaking driver', 'Fuel, parking and highway tolls', 'Airport pickup and drop-off', 'Driver''s meals and accommodation'],
 array['International flights', 'Accommodation unless arranged in your quotation', 'Entrance tickets and safari jeeps', 'Meals', 'Personal expenses and tips'],
 '[{"name":"Reserved train seats","description":"Hill-country train, subject to availability"},{"name":"Tea factory visit with tasting","description":"Nuwara Eliya or Ella"},{"name":"Whale watching from Mirissa","description":"Roughly November to April"}]'::jsonb,
 'https://images.unsplash.com/photo-1568843240915-b512cc9b4415', 'The white lighthouse at Galle Fort', 'Photo: Shainee Fernando / Unsplash',
 'Grand Tour of Sri Lanka: 14-day private tour', 'Two weeks around Sri Lanka with a private driver: Anuradhapura region, Kandy, Ella, Yala, Galle and the beaches.',
 false, 'published', 3),

('south-coast-beaches-and-yala', 'South Coast Beaches & Yala',
 'Galle Fort, palm-lined bays and a leopard safari in Yala.',
 'Slow days on the south coast combined with an early-morning safari in Yala National Park, home to one of the highest densities of leopards in the world. Best from November to April, when the south coast seas are calm.',
 array['beach', 'wildlife'], 6, 5,
 array['Couples', 'Honeymooners', 'Families'], array['Car', 'SUV'], 8, 'QUOTE_ONLY',
 array['Private air-conditioned vehicle with driver', 'Fuel, parking and highway tolls', 'Airport pickup and drop-off'],
 array['Safari jeep and park fees', 'Accommodation unless arranged in your quotation', 'Meals', 'Personal expenses and tips'],
